  if(session.evidence)return;pullArmed=false;xrMenu='main';session.playing=false;xrBriefing=xrWorkOrder=xrComparing=xrReadingResult=false;xrPage=0;
  plantView=a==='planning-table'?null:a==='plant-overview'?'overview':a==='approach'?'entrance':plantView?PLANT_VIEWS[plantView].next:null;
