const equipmentRay=new T.Raycaster();let pointerStart:{x:number;y:number}|null=null;renderer.domElement.addEventListener('pointerdown',e=>{if(e.button===0)pointerStart={x:e.clientX,y:e.clientY};});renderer.domElement.addEventListener('pointerup',e=>{const start=pointerStart;pointerStart=null;if(!start||Math.hypot(e.clientX-start.x,e.clientY-start.y)>5||renderer.xr.isPresenting)return;const rect=renderer.domElement.getBoundingClientRect();equipmentRay.setFromCamera(new T.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);const hit=pickEquipment(equipmentRay,model.group);if(hit)selectWork(hit.workOrderId,hit.equipmentId);});
