const callout=model.marker.getObjectByName('contact-callout-label') as T.Sprite|undefined,calloutLeader=model.marker.getObjectByName('contact-callout-leader');const calloutPoint=new T.Vector3(),cameraPoint=new T.Vector3(),worldScale=new T.Vector3();
function updateContactAnnotation(){if(!callout)return;const activeCamera=renderer.xr.isPresenting?renderer.xr.getCamera().cameras[0]??camera:camera;model.group.updateMatrixWorld(true);activeCamera.updateMatrixWorld(true);callout.getWorldPosition(calloutPoint);cameraPoint.copy(calloutPoint).applyMatrix4(activeCamera.matrixWorldInverse);calloutPoint.project(activeCamera);const reading=contextCoach.sprite.visible||!!session.evidence||xrBriefing||xrReadingResult||xrComparing||xrWorkOrder||xrMenu!=='main'||!!plantView;const layout=contactAnnotationLayout(calloutPoint.x,calloutPoint.y,-cameraPoint.z,activeCamera.projectionMatrix.elements[0],activeCamera.projectionMatrix.elements[5],reading);callout.visible=layout.visible;calloutLeader!.visible=layout.visible;model.group.getWorldScale(worldScale);callout.scale.set(layout.width/worldScale.x,layout.height/worldScale.y,1);}
let lastCoachingKey='';function updateContextCoach(){const input=coachingInput(),visible=!plantView&&!pending&&!session.evidence&&!xrBriefing&&!xrWorkOrder&&!xrComparing&&!xrReadingResult&&xrMenu==='main'&&(pullArmed||input.grip!=='idle')&&!guide.state.enabled;const cam=renderer.xr.isPresenting?renderer.xr.getCamera().cameras[0]??camera:camera;contextCoach.update(input,model.group.getObjectByName('pinch-handle')!,cam,visible);const key=coachingCue(input).title;if(key!==lastCoachingKey){lastCoachingKey=key;if(compactTask())drawXR();}}
let last=performance.now(),lastSoundProgress=session.progress,lastAudibleMotion=false;scene.onBeforeRender=()=>{const time=performance.now(),dt=Math.max(0,(time-last)/1000);last=time;if(transition){transition.elapsed+=dt;fadeMaterial.opacity=transition.elapsed<=.12?Math.min(1,transition.elapsed/.12):Math.max(0,(.24-transition.elapsed)/.12);if(transition.elapsed>=.12&&!transition.committed){transition.committed=true;applyViewNow();}if(transition.elapsed>=.24){transition=null;fadeMesh.visible=false;drawXR();}}updateContextCoach();updateContactAnnotation();if(modelReview)modelReview.update();if(session.playing){session.tick(dt);sync();updatePose();if(!session.playing)drawXR();}const moved=Math.abs(session.progress-lastSoundProgress)>1e-6;const audiblyMoving=moved&&(session.playing||handInput.capture.kind==='grab')&&!session.needsResume;sound.motion(audiblyMoving);const stop=moved&&sound.enabled?(session.effective.issues.find(i=>i.code==='PATH_BLOCKED')?.progress??1):1;if(session.progress>=stop&&lastSoundProgress<stop&&moved&&(audiblyMoving||lastAudibleMotion))sound.contact();lastAudibleMotion=audiblyMoving;lastSoundProgress=session.progress;if(!renderer.xr.isPresenting)controls.update();};render();applyViewNow();resize();
